kills.mutated_unit_code:
function withdraw()
    payable
    public
    {
        require(msg.sender == Owner);
        (bool success, ) = Owner.call{value: address(this).balance}("");
        // ignore success
    }

function Command(address adr,bytes memory data)
    payable
    public
    {
        require(msg.sender == Owner);

        (bool success, ) = adr.call{value: msg.value}(data);
        require(success);
    }
